import sys

def main():
    data = sys.stdin.read().split()
    n, T = int(data[0]), int(data[1])
    dist = [int(x) for x in data[2:2 + n]]
    head, last = dist[:-1], dist[-1]

    def ok(v):
        s = 0
        for d in head:
            s += -(-d // v)
        return 100 * s + -(-100 * last // v) <= T

    lo, hi = 1, 10 ** 7
    if not ok(hi):
        print(-1)
        return
    while lo < hi:
        mid = (lo + hi) // 2
        if ok(mid):
            hi = mid
        else:
            lo = mid + 1
    print(lo)

main()

